// Minimal ambient types for the Web Speech API. TypeScript's DOM lib already
// declares SpeechRecognitionEvent/SpeechRecognitionErrorEvent/SpeechRecognitionResult(List);
// only the SpeechRecognition interface itself and its Window entry points are missing.

interface SpeechRecognition extends EventTarget {
  lang: string;
  continuous: boolean;
  interimResults: boolean;
  maxAlternatives: number;
  start(): void;
  stop(): void;
  abort(): void;
  onresult: ((event: SpeechRecognitionEvent) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null;
  onend: (() => void) | null;
}

interface Window {
  SpeechRecognition?: { new (): SpeechRecognition };
  webkitSpeechRecognition?: { new (): SpeechRecognition };
}
